// Convierte cada embajador de Apoya2 en el body de /api/bot/upsert_contact
const TENANT_ID = 'f31be830-125f-4c61-9779-854607cac89c';
const clean = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const titleCase = (s) => s.toLowerCase().replace(/(^|[\s'-])\S/g, (c) => c.toUpperCase());

const out = [];
for (const { json: e } of $input.all()) {
  let nombre = clean(e.NombreEmbajador);
  // "RICARDO  DIAZ " -> "Ricardo Diaz" (solo si viene todo en mayúsculas o minúsculas)
  if (nombre && (nombre === nombre.toUpperCase() || nombre === nombre.toLowerCase())) nombre = titleCase(nombre);

  let phone = String(e.CelularEmbajador ?? '').replace(/\D/g, '');
  if (phone.startsWith('00')) phone = phone.slice(2);
  if (phone.length === 10 && phone.startsWith('3')) phone = '57' + phone; // celular colombiano -> 57XXXXXXXXXX
  if (!/^57\d{10}$/.test(phone)) continue; // sin celular válido no se puede crear (el WhatsApp es la llave del contacto)

  const email = clean(e.CorreoEmbajador).toLowerCase();
  const fecha = clean(e.FechaCreacion).slice(0, 10); // "2024-11-29 15:53:51.127" -> "2024-11-29"

  const fields = {
    id_persona: e.IdPersona,
    id_embajador: e.IdEmbajador,
    id_manychat: e.IdManychatEmbajador,
    link_referido: e.LinkCorto,
    localidad: e.NombreGrupo,
    clientes_referidos: e.NumeroClientesReferidos,
    fecha_registro_apoya2: /^\d{4}-\d{2}-\d{2}$/.test(fecha) ? fecha : '',
  };
  // Los vacíos no se envían (así no se borra un valor que ya esté en el CRM)
  for (const k of Object.keys(fields)) {
    const v = clean(fields[k]);
    if (v) fields[k] = v; else delete fields[k];
  }

  out.push({
    json: {
      tenant_id: TENANT_ID,
      phone,               // siempre 57 + 10 dígitos
      nombre: nombre || phone,
      ...(email ? { email } : {}),
      fields,
      tags: ['Embajador'],
      reason: 'Sincronización de embajadores desde Apoya2',
    },
  });
}
return out;

// Resumen de la sincronización
const recibidos = $('API Embajadores').all().length;
const enviados = $('Preparar contactos').all();
const resultados = $input.all();

let creados = 0, actualizados = 0, sinCambios = 0;
const errores = [];
resultados.forEach((r, i) => {
  const j = r.json;
  const p = enviados[i]?.json ?? {};
  if (j.ok) {
    if (j.data?.created) creados++;
    else if (j.data?.updated) actualizados++;
    else sinCambios++;
  } else {
    errores.push({ nombre: p.nombre, phone: p.phone, error: j.error?.message ?? j.error ?? JSON.stringify(j).slice(0, 200) });
  }
});

return [{
  json: {
    recibidos_api: recibidos,
    omitidos_sin_celular_valido: recibidos - enviados.length,
    enviados_crm: enviados.length,
    creados,
    actualizados,
    sin_cambios: sinCambios,
    errores: errores.length,
    detalle_errores: errores,
  },
}];
